            return;
        }
        this.systems.put(name, system);
        MinimapLogs.LOGGER.info("Registered synced player tracker system: " + name);
    }

    public Iterable<ISyncedPlayerTrackerSystem> getSystems() {
        return this.systems.values();
    }
}

